.darma-loader-darma-b13-punching-bag { --accent: var(--loader-color, #b91c1c); --accent-2: var(--loader-secondary-color, #fbbf24); width: calc(var(--loader-size, 112px) * .72); height: var(--loader-size, 112px); position: relative; }
.darma-loader-darma-b13-punching-bag::before { content: ''; position: absolute; top: 0; left: 47%; width: 6%; height: 22%; background: repeating-linear-gradient(to bottom, #94a3b8 0 24%, transparent 24% 36%); }
.darma-loader-darma-b13-punching-bag .darma-loader-darma-b13-punching-bag__bag { position: absolute; top: 18%; left: 26%; width: 48%; height: 64%; border-radius: 26% 26% 34% 34%; background: linear-gradient(var(--accent), color-mix(in srgb, #000 30%, var(--accent))); box-shadow: inset calc(var(--loader-size, 112px) * .04) 0 calc(var(--loader-size, 112px) * .06) rgba(255, 255, 255, .22); transform-origin: top center; animation: darma-loader-darma-b13-punching-bag-swing calc(var(--loader-speed, 1s) * 1.8) ease-in-out infinite; }
.darma-loader-darma-b13-punching-bag .darma-loader-darma-b13-punching-bag__bag::after { content: ''; position: absolute; top: 34%; left: 0; width: 100%; height: 9%; background: color-mix(in srgb, #fff 70%, var(--accent)); }
.darma-loader-darma-b13-punching-bag span { position: absolute; top: 38%; right: 0; width: 26%; height: 22%; background: var(--accent-2); clip-path: polygon(50% 0, 61% 35%, 98% 35%, 68% 57%, 79% 91%, 50% 70%, 21% 91%, 32% 57%, 2% 35%, 39% 35%); animation: darma-loader-darma-b13-punching-bag-impact calc(var(--loader-speed, 1s) * 1.8) ease-out infinite; }
@keyframes darma-loader-darma-b13-punching-bag-swing { 0%, 100% { transform: rotate(-14deg); } 50% { transform: rotate(14deg); } }
@keyframes darma-loader-darma-b13-punching-bag-impact { 0%, 74% { opacity: 0; transform: scale(.4); } 82% { opacity: 1; transform: scale(1.15); } 92%, 100% { opacity: 0; transform: scale(.6); } }

